from .betreuungsrechnung import _rechnungssumme
from .betraege import _geld_ergebnis
from .kalender import _auswahl, _text

_FAELLE = {'grundstueck_erschliessungsbeitraege_verkaeufer': '§436I: vom Verkäufer zu tragende Erschließungs- und sonstige Anliegerbeiträge für Maßnahmen, die bis einschließlich des Vertragsschlusstages bautechnisch begonnen sind. Beginn und Zuordnung jeder Maßnahme vorqualifiziert; Entstehungsdatum der Beitragsschuld ist hierfür nicht maßgeblich. Keine abweichende Vereinbarung; sonstige öffentliche Lasten436II nicht pauschal einbeziehen.', 'kauf_uebergabekosten_verkaeufer': '§448I: rechtlich zugeordnete Kosten der Übergabe der Sache zulasten des Verkäufers. Kosten der Abnahme oder Versendung an einen anderen Ort als den Erfüllungsort gehören nicht hierher. Abweichende Kostenvereinbarungen und Sonderregeln vorqualifizieren.', 'kauf_abnahme_versand_grundbuchkosten_kaeufer': '§448I/II: rechtlich zugeordnete Käuferkosten der Abnahme und Versendung an einen anderen Ort als den Erfüllungsort sowie bei Grundstückskauf Beurkundung des Kaufvertrags und der Auflassung, Grundbucheintragung und erforderliche Erklärungen. Nur tatsächlich einschlägige Kostenkategorien einbeziehen; keine Berechnung von Gebührensätzen. Abweichende Vereinbarungen und Sonderregeln vorqualifizieren.', 'zahlung_fehlerentgelte_zinsen': '§675yVI: in Zusammenhang mit nicht erfolgter oder fehlerhafter Ausführung in Rechnung gestellte oder belastete Entgelte und Zinsen; nur rechtlich erstattungsfähige Positionen. Zahlungsbetrag und dessen Kontokorrektur sowie sonstiger Schaden675z getrennt halten. Jede Gebühr/Zinsposition nur einmal, bereits erstattete Beträge separat anrechnen.', 'landpacht_notwendige_verwendungen': '§590b: notwendige Verwendungen auf die Pachtsache; rechtliche Erforderlichkeit und Pflichtenzuordnung vorqualifiziert. Andere als notwendige Verwendungen591 und Wegnahmerechte591a gesondert. Vorschüsse oder geleisteter Ersatz sind keine zusätzlichen Verwendungen.', 'vergebliche_vertrauensaufwendungen': '§284: nur billigerweise im Vertrauen auf Leistung getätigte, ersatzfähige vergebliche Aufwendungen. Alternative zum Schadensersatz statt der Leistung; kein zusätzlicher Ersatz beider Positionen. Zweckverfehlung auch ohne Pflichtverletzung, Zurechnung und weitere Anspruchsgrenzen vorqualifizieren.', 'mietmangel_selbstbeseitigung': '§536aII: erforderliche Selbstbeseitigungsaufwendungen bei vorqualifiziertem Vermieterverzug oder notwendiger umgehender Bestandserhaltung/-wiederherstellung. Schadensersatz536aI separat;536b/c/d, Kenntnis, Anzeige und wirksame Vertragsregelungen vorqualifizieren.', 'miete_erhaltung_modernisierung': '§555aIII und555dVI: infolge Erhaltungs-/Modernisierungsmaßnahme notwendige, im angemessenen Umfang ersatzfähige Mieteraufwendungen. Keine Modernisierungsumlage559; Vorschüsse und bereits geleisteter Ersatz separat anrechnen, nicht nochmals als Aufwand zählen.', 'auftrag_aufwendungen': '§670: zum Zwecke der Auftragsausführung gemachte Aufwendungen, die den Umständen nach für erforderlich gehalten werden durften. Keine automatische Vergütung eigener Tätigkeit; Vorschuss669 und Herausgabe667 getrennt abrechnen.', 'kauf_nacherfuellung': '§439II/III/VI2: erforderliche Nacherfüllungsaufwendungen einschließlich qualifizierter Transport-, Wege-, Arbeits-, Material-, Ausbau-/Einbau- und Rücknahmekosten. Anspruchsvoraussetzungen, Verweigerungsrechte und konkrete Zuordnung vorqualifizieren; keine Doppelzählung von Material in Gesamtwerkrechnung.', 'lieferantenregress': '§445aI/III: im konkreten Lieferverhältnis regressfähige Aufwendungen aus439II/III/VI2 und475V. Neu hergestellte Sache, maßgeblicher Mangel/Aktualisierungspflicht und gegebenenfalls Unternehmereigenschaft der Lieferkette vorqualifiziert. Nicht sämtliche eigenen Betriebskosten; weitere Rechte und377HGB gesondert.', 'teilzeitwohnrecht_widerrufskosten': '§357cI: dem Verbraucher zu erstattende Vertrags-, Durchführungs- und Rückabwicklungskosten nach qualifiziertem Widerruf. Keine Vergütung von Diensten/Nutzungsüberlassung zugunsten des Unternehmers einrechnen; etwaiger Wertersatz357cII separat, nicht automatisch aufrechnen.', 'teilzahlung_ruecktritt_508': '§508Satz3/6: infolge des Vertrags gemachte, rechtlich ersatzfaehige Unternehmeraufwendungen im qualifizierten Ruecktrittsverhaeltnis. Positionen ohne Doppelzaehlung summieren. Nutzungsverguetung nachSatz4 unter Ruecksicht auf eingetretene Wertminderung gesondert bewerten; keine pauschale Gleichsetzung mit Wertverlust und kein automatischer doppelter Abzug. Gewoehnlicher Verkaufswert bei Vereinbarung nachSatz5 ist externe Bewertung zum Wegnahmezeitpunkt, keine gesetzliche Prozentformel; dieser alternative Weg nicht mit automatischem Ruecktritt vermischen.'}

def schuldrecht_aufwendungssumme(regelfall=None, aufwendungspositionen=None, einordnungsnachweis=None):
    """Nichtnegative, ohne Überschneidung rechtlich zugeordnete Aufwendungspositionen exakt summieren."""
    _auswahl(regelfall,"regelfall",tuple(_FAELLE))
    summe = _rechnungssumme(aufwendungspositionen,"aufwendungspositionen")
    _text(einordnungsnachweis,"einordnungsnachweis")
    eingaben = dict(regelfall=regelfall, aufwendungspositionen=aufwendungspositionen, einordnungsnachweis=einordnungsnachweis)
    ergebnis = _geld_ergebnis(summe,'BGB_SCHULDRECHT_AUFWENDUNGSSUMME',eingaben,[dict(operation='Nichtnegative, ohne Überschneidung rechtlich zugeordnete Aufwendungspositionen exakt summieren.')])
    ergebnis["hinweise"].extend(['Nur numerischer Summenbaustein; Anspruchsvoraussetzungen, Erforderlichkeit/Angemessenheit und rechtliche Einwendungen vorab bestimmen. Positionsbelege bleiben notwendig. Vorschüsse, Erstattungen und Zahlungen separat zuordnen; Summe ist kein ungeprüfter offener Zahlungsanspruch.',_FAELLE[regelfall]])
    return ergebnis
